#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)
#define D (int)4
#define K (int)1000
#define N (int)4e+6

int dx[D]={-1,1,0,0};
int dy[D]={0,0,-1,1};

int h,w;
string s[K];
int sx,gx,sy,gy;
vector<int>e[N+2];
int prv[N+2];

void init(void){
	rep(i,h)rep(j,w){
		rep(d,D)prv[(i*K+j)*D+d]=-1;
		if(s[i][j]=='#')continue;
		if(s[i][j]=='S'){sx=i;sy=j;}
		if(s[i][j]=='G'){gx=i;gy=j;}
		rep(d2,D){
			if((i+dx[d2]>=0)&&(i+dx[d2]<h)&&(j+dy[d2]>=0)&&(j+dy[d2]<w)&&s[i+dx[d2]][j+dy[d2]]!='#'){
				rep(d1,D){
					int idx1=(i*K+j)*D+d1;
					int idx2=((i+dx[d2])*K+(j+dy[d2]))*D+d2;
					if((d1!=d2)&&(s[i][j]!='o'))e[idx1].push_back(idx2);
					if((d1==d2)&&(s[i][j]!='x'))e[idx1].push_back(idx2);
				}
			}
		}

	}
	rep(sd,4)e[N].push_back((sx*K+sy)*D+sd);
	rep(gd,4)e[(gx*K+gy)*D+gd].push_back(N+1);
	prv[N]=-2; prv[N+1]=-1;
	return;
}

int main(void){
	cin>>h>>w;
	rep(i,h)cin>>s[i];
	init();

	queue<int>q;
	q.push(N);
	bool flag=false;
	while(!q.empty()){
		int k=q.front();
		q.pop();
		int sz=e[k].size();
		rep(i,sz){
			if(prv[e[k][i]]==-1){
				prv[e[k][i]]=k;
				q.push(e[k][i]);
				if(e[k][i]==(N+1))flag=true;
			}
		}
		if(flag)break;
	}

	if(flag){
		string ans;
		int cur=prv[N+1];
		while(prv[cur]!=N){
			int x=(prv[cur]/D)/K;
			int y=(prv[cur]/D)%K;
			int x2=(cur/D)/K;
			int y2=(cur/D)%K;
			if(x2==x-1)ans+="U";
			if(x2==x+1)ans+="D";
			if(y2==y-1)ans+="L";
			if(y2==y+1)ans+="R";
			cur=prv[cur];
		}
		reverse(ans.begin(), ans.end());
		cout<<"Yes"<<endl;
		cout<<ans<<endl;
	}
	else{
		cout<<"No"<<endl;
	}

	return 0;
}
